package controller;
import model.User;import util.DBConnection;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;import java.time.*;
@WebServlet("/modify-booking") public class BookingModifyServlet extends HttpServlet{
 protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{HttpSession h=q.getSession(false);User u=h==null?null:(User)h.getAttribute("user");if(u==null){s.sendRedirect("login.jsp");return;}try{int id=Integer.parseInt(q.getParameter("bookingId"));LocalDate a=LocalDate.parse(q.getParameter("pickupDate")),b=LocalDate.parse(q.getParameter("returnDate"));if(a.isBefore(LocalDate.now())||!b.isAfter(a))throw new IllegalArgumentException();try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("SELECT b.car_id,c.price_per_day FROM bookings b JOIN cars c ON c.car_id=b.car_id WHERE b.booking_id=? AND b.user_id=? AND b.booking_status IN ('Pending','Booked') FOR UPDATE OF b")){p.setInt(1,id);p.setInt(2,u.getUserId());try(ResultSet r=p.executeQuery()){if(!r.next()){c.rollback();s.sendRedirect("bookingHistory.jsp?modify=unavailable");return;}int car=r.getInt(1);double price=r.getDouble(2);try(PreparedStatement x=c.prepareStatement("SELECT 1 FROM bookings WHERE car_id=? AND booking_id<>? AND booking_status IN ('Pending','Booked','Delivered') AND pickup_date < ? AND return_date > ? LIMIT 1")){x.setInt(1,car);x.setInt(2,id);x.setDate(3,Date.valueOf(b));x.setDate(4,Date.valueOf(a));try(ResultSet overlap=x.executeQuery()){if(overlap.next()){c.rollback();s.sendRedirect("bookingHistory.jsp?modify=unavailable");return;}}}try(PreparedStatement x=c.prepareStatement("UPDATE bookings SET pickup_date=?,return_date=?,total_amount=? WHERE booking_id=? AND user_id=?")){x.setDate(1,Date.valueOf(a));x.setDate(2,Date.valueOf(b));x.setDouble(3,Duration.between(a.atStartOfDay(),b.atStartOfDay()).toDays()*price);x.setInt(4,id);x.setInt(5,u.getUserId());x.executeUpdate();}}}c.commit();}s.sendRedirect("bookingHistory.jsp?modify=success");}catch(Exception e){s.sendRedirect("bookingHistory.jsp?modify=invalid");}}
}
